export class MapNavigation {
 constructor(data){this.floorBuckets=new Map();for(const m of data.meshes||[])for(let i=0;i<m.positions.length;i+=9){if(m.normals[i+1]<.65)continue;const p=m.positions.slice(i,i+9),xs=[p[0],p[3],p[6]],zs=[p[2],p[5],p[8]];for(let x=Math.floor(Math.min(...xs)/4);x<=Math.floor(Math.max(...xs)/4);x++)for(let z=Math.floor(Math.min(...zs)/4);z<=Math.floor(Math.max(...zs)/4);z++){const k=x+','+z;if(!this.floorBuckets.has(k))this.floorBuckets.set(k,[]);this.floorBuckets.get(k).push(p);}}this.wallBuckets=new Map();for(const line of data.wallSegments||[]){for(let x=Math.floor(Math.min(line[0],line[2])/4);x<=Math.floor(Math.max(line[0],line[2])/4);x++)for(let z=Math.floor(Math.min(line[1],line[3])/4);z<=Math.floor(Math.max(line[1],line[3])/4);z++){const k=x+','+z;if(!this.wallBuckets.has(k))this.wallBuckets.set(k,[]);this.wallBuckets.get(k).push(line);}}this.data=data;this.areas=data.areas;this.byId=new Map(this.areas.map(a=>[a.id,a]));this.bounds=data.bounds;this.buckets=new Map();for(const a of this.areas){const b=a.bounds;for(let x=Math.floor(b[0]/4);x<=Math.floor(b[2]/4);x++)for(let z=Math.floor(b[1]/4);z<=Math.floor(b[3]/4);z++){const k=x+','+z;if(!this.buckets.has(k))this.buckets.set(k,[]);this.buckets.get(k).push(a);}}if(data.navigationVersion!==2)this.connectNearby();this.normalizePoints();}
 normalizePoints(){
  this.data.sites=this.data.sites.map(s=>this.safePoint(s));
  // Reachability must repair navigation links, never teleport a spawn across
  // the map to the first site's connected component.
  for(const side of ['attack','defend'])this.data.spawns[side]=this.data.spawns[side].map(p=>this.safePoint(p));
 }

 height(a,x,z){const b=a.bounds,u=Math.max(0,Math.min(1,(x-b[0])/(b[2]-b[0]||1))),v=Math.max(0,Math.min(1,(z-b[1])/(b[3]-b[1]||1)));return (a.heights[0]*(1-u)+a.heights[1]*u)*(1-v)+(a.heights[2]*(1-u)+a.heights[3]*u)*v;}
 areaAt(x,z,floor=0){const near=this.buckets.get(Math.floor(x/4)+','+Math.floor(z/4))||[];let chosen=null,best=Infinity;for(const a of near){const b=a.bounds;if(x<b[0]-.05||x>b[2]+.05||z<b[1]-.05||z>b[3]+.05)continue;const d=Math.abs(this.height(a,x,z)-floor);if(a.walkable!==false&&d<best){best=d;chosen=a;}}return chosen;}
 nearest(x,z,floor=0){let best=Infinity,chosen;for(const a of this.areas){const b=a.bounds,d=Math.max(b[0]-x,0,x-b[2])**2+Math.max(b[1]-z,0,z-b[3])**2+Math.abs(this.height(a,x,z)-floor)*.15;if(a.walkable!==false&&d<best){best=d;chosen=a;}}return chosen;}
 floorAt(x,z,floor=0,maxHeight=Infinity){const surfaces=this.floorBuckets.get(Math.floor(x/4)+','+Math.floor(z/4));if(surfaces){let h=null,best=Infinity;for(const p of surfaces){const den=(p[5]-p[8])*(p[0]-p[6])+(p[6]-p[3])*(p[2]-p[8]);if(Math.abs(den)<1e-8)continue;const a=((p[5]-p[8])*(x-p[6])+(p[6]-p[3])*(z-p[8]))/den,b=((p[8]-p[2])*(x-p[6])+(p[0]-p[6])*(z-p[8]))/den,c=1-a-b;if(Math.min(a,b,c)<-.0001)continue;const y=a*p[1]+b*p[4]+c*p[7],d=Math.abs(y-floor);if(y>maxHeight||d>=best)continue;if(this.data.useBspCollision&&(this.contents(x,y+.08,z)===-2||this.contents(x,y-.08,z)!==-2))continue;if(d<best){best=d;h=y;}}if(h!==null)return h;}let a=this.areaAt(x,z,floor);if(!a){const near=this.buckets.get(Math.floor(x/4)+','+Math.floor(z/4))||[];a=near.find(a=>{const b=a.bounds;return Math.max(b[0]-x,0,x-b[2])<.5&&Math.max(b[1]-z,0,z-b[3])<.5&&Math.abs(this.height(a,x,z)-floor)<.76;});}return a?this.height(a,x,z):null;}
 connectNearby(){const checked=new Set();for(const a of this.areas){const b=a.bounds;for(let x=Math.floor(b[0]/4)-1;x<=Math.floor(b[2]/4)+1;x++)for(let z=Math.floor(b[1]/4)-1;z<=Math.floor(b[3]/4)+1;z++)for(const c of this.buckets.get(x+','+z)||[]){if(c===a)continue;const key=[a.id,c.id].sort((x,y)=>x-y).join(',');if(checked.has(key))continue;checked.add(key);const d=c.bounds,dx=Math.max(b[0]-d[2],d[0]-b[2],0),dz=Math.max(b[1]-d[3],d[1]-b[3],0);if(dx>.65||dz>.65)continue;const px=(Math.max(b[0],d[0])+Math.min(b[2],d[2]))/2,pz=(Math.max(b[1],d[1])+Math.min(b[3],d[3]))/2,ha=this.floorAt(px,pz,this.height(a,px,pz)),hc=this.floorAt(px,pz,this.height(c,px,pz));if(Math.abs(ha-hc)>1.12)continue;let clear=true;for(const [ox,oz]of [[0,0],[.2,0],[-.2,0],[0,.2],[0,-.2]])for(const h of [.4,1.4])if(this.contents(px+ox,Math.max(ha,hc)+h,pz+oz)===-2||this.wallBlocked(px,pz,.25,Math.max(ha,hc)))clear=false;if(clear){if(!a.links.includes(c.id))a.links.push(c.id);if(!c.links.includes(a.id))c.links.push(a.id);}}}}
 safePoint(point){point={...point,floor:this.floorAt(point.x,point.z,point.floor)??point.floor};if(!this.blocked(point.x,point.z,.37,point.floor)){const a=this.areaAt(point.x,point.z,point.floor);if(this.data.navigationVersion===2&&a?.walk&&!this.trace(point,a.walk))return {...point,...a.walk};return point;}let closest=null,best=Infinity;for(const a of this.areas){const p=this.center(a),distance=(p.x-point.x)**2+(p.z-point.z)**2+Math.abs(p.floor-point.floor)*4;if(a.walkable!==false&&Math.hypot(p.x-point.x,p.z-point.z)<6&&distance<best&&!this.blocked(p.x,p.z,.37,p.floor)){best=distance;closest=p;}}return closest?{...point,...closest}:point;}
 contents(x,y,z){const d=this.data;for(const root of d.roots){if(typeof root==='object'){const b=root.bounds;if(x*32<b[0]||x*32>b[3]||-z*32<b[1]||-z*32>b[4]||y*32<b[2]||y*32>b[5])continue;}let n=typeof root==='object'?root.node:root;for(let i=0;i<1000;i++){if(n<0){if(d.leaves[-n-1]===-2)return -2;break;}const [p,a,b]=d.nodes[n],[nx,ny,nz,dist]=d.planes[p];n=nx*x*32-ny*z*32+nz*y*32-dist>=0?a:b;}}return -1;}
 wallBlocked(x,z,r,floor){if(this.data.useBspCollision)return false;for(let bx=Math.floor((x-r)/4);bx<=Math.floor((x+r)/4);bx++)for(let bz=Math.floor((z-r)/4);bz<=Math.floor((z+r)/4);bz++)for(const [ax,az,bx1,bz1,lo,hi]of this.wallBuckets.get(bx+','+bz)||[]){if(hi<floor+.25||lo>floor+1.5)continue;const dx=bx1-ax,dz=bz1-az,t=Math.max(0,Math.min(1,((x-ax)*dx+(z-az)*dz)/(dx*dx+dz*dz||1)));if(Math.hypot(x-ax-dx*t,z-az-dz*t)<r)return true;}return false;}
 bodyBlocked(x,z,r,feet,height=1.65){for(const [dx,dz]of [[0,0],[r,0],[-r,0],[0,r],[0,-r]])for(const h of [.12,height*.5,height-.12])if(this.contents(x+dx,feet+h,z+dz)===-2)return true;return false;}

 blocked(x,z,r=.37,floor=0,step=.76){const next=this.floorAt(x,z,floor);if(next===null||Math.abs(next-floor)>step||this.wallBlocked(x,z,r,next))return true;for(const [dx,dz]of [[0,0],[r,0],[-r,0],[0,r],[0,-r]])for(const h of [Math.max(.82,step+.05),Math.max(1,step+.05),1.55])if(this.contents(x+dx,next+h,z+dz)===-2)return true;return false;}
 center(a){if(a.walk)return {...a.walk};const b=a.bounds,x=(b[0]+b[2])/2,z=(b[1]+b[3])/2;return{x,z,floor:this.height(a,x,z)};}
 trace(a,b,r=.37){for(const stride of [.04,.07,.125]){let {x,z,floor}=a,reached=false;const limit=Math.max(30,Math.ceil(Math.hypot(b.x-x,b.z-z)/stride)*3+5);for(let i=0;i<limit;i++){const distance=Math.hypot(b.x-x,b.z-z);if(distance<.002){reached=Math.abs(floor-b.floor)<.12;break;}const step=Math.min(stride,distance),dx=(b.x-x)/distance*step,dz=(b.z-z)/distance*step,oldX=x,oldZ=z;if(!this.blocked(x+dx,z,r,floor,1.12))x+=dx;if(!this.blocked(x,z+dz,r,floor,1.12))z+=dz;if(x===oldX&&z===oldZ)return false;floor=this.floorAt(x,z,floor);}if(!reached)return false;}return true;}

 portal(a,b){const A=a.bounds,B=b.bounds,range=(l,h,m,n)=>[Math.max(l,m),Math.min(h,n)];let[x0,x1]=range(A[0],A[2],B[0],B[2]),[z0,z1]=range(A[1],A[3],B[1],B[3]);if(x0>x1){const x=(x0+x1)/2;x0=x1=x;}if(z0>z1){const z=(z0+z1)/2;z0=z1=z;}for(const u of [.5,.25,.75,.1,.9])for(const v of [.5,.25,.75,.1,.9]){if(x0===x1&&u!==.5||z0===z1&&v!==.5)continue;const x=x0+(x1-x0)*u,z=z0+(z1-z0)*v,h=this.floorAt(x,z,(a.walk.floor+b.walk.floor)/2),q={x,z,floor:h};if(this.trace(a.walk,q,.39)&&this.trace(q,b.walk,.39)&&this.trace(b.walk,q,.39)&&this.trace(q,a.walk,.39))return q;}return null;}
 compileWalkGraph(){const floors=[...this.data.sites,...this.data.spawns.attack,...this.data.spawns.defend].map(p=>p.floor),lo=Math.min(...floors)-8,hi=Math.max(...floors)+8;for(const a of this.areas){delete a.via;const b=a.bounds,c=this.center(a);if(c.floor<lo||c.floor>hi){a.walkable=false;a.walk=null;a.links=[];continue;}let chosen=null,best=Infinity;for(const u of [.5,.25,.75,.1,.9])for(const v of [.5,.25,.75,.1,.9]){const x=b[0]+(b[2]-b[0])*u,z=b[1]+(b[3]-b[1])*v,floor=this.floorAt(x,z,this.height(a,x,z)),d=(x-c.x)**2+(z-c.z)**2;if(floor!==null&&d<best&&!this.blocked(x,z,.39,floor)){best=d;chosen={x,z,floor};}}a.walk=chosen;a.walkable=!!chosen;}let count=0;const edges=new Map();for(const a of this.areas){a.links=a.links.filter(id=>{const b=this.byId.get(id);if(!a.walkable||!b?.walkable)return false;const k=[a.id,id].sort((a,b)=>a-b).join(',');if(!edges.has(k))edges.set(k,this.trace(a.walk,b.walk,.39)&&this.trace(b.walk,a.walk,.39)?true:this.portal(a,b));const result=edges.get(k);if(result&&result!==true){(a.via??={})[id]=result;(b.via??={})[a.id]=result;}return !!result;});count+=a.links.length;}this.data.navigationVersion=2;this.normalizePoints();return count;}
 transition(a,b){
  this.checkedTransitions??=new Map((this.data.transitionVersion===1?this.data.verifiedTransitions||[]:[]).map(key=>[key,true]));a.walk??=this.center(a);b.walk??=this.center(b);const key=[a.id,b.id].sort((x,y)=>x-y).join(',');if(this.checkedTransitions.has(key))return this.checkedTransitions.get(key);
  let via=a.via?.[b.id]||b.via?.[a.id];if(via)via={...via,floor:this.floorAt(via.x,via.z,(a.walk.floor+b.walk.floor)/2)};
  let pass=via?this.trace(a.walk,via)&&this.trace(via,b.walk)&&this.trace(b.walk,via)&&this.trace(via,a.walk):this.trace(a.walk,b.walk)&&this.trace(b.walk,a.walk);
  if(!pass){if(this.trace(a.walk,b.walk)&&this.trace(b.walk,a.walk)){pass=true;via=null;}else{via=this.portal(a,b);pass=!!via;}}
  if(pass&&via){(a.via??={})[b.id]=via;(b.via??={})[a.id]=via;}else{if(a.via)delete a.via[b.id];if(b.via)delete b.via[a.id];}
  if(!pass){a.links=a.links.filter(id=>id!==b.id);b.links=b.links.filter(id=>id!==a.id);}this.checkedTransitions.set(key,pass);return pass;
 }
 path(sx,sz,tx,tz,floor=0,targetFloor=floor){
  const start=this.areaAt(sx,sz,floor)||this.nearest(sx,sz,floor),goal=this.areaAt(tx,tz,targetFloor)||this.nearest(tx,tz,targetFloor);if(!start||!goal)return[];
  for(let attempt=0;attempt<=this.areas.length;attempt++){
   const queue=[start.id],from=new Map([[start.id,null]]);let found=false;for(let at=0;at<queue.length;at++){const id=queue[at];if(id===goal.id){found=true;break;}for(const next of this.byId.get(id).links)if(this.byId.has(next)&&this.byId.get(next).walkable!==false&&!from.has(next)){from.set(next,id);queue.push(next);}}
   if(!found)return[];const chain=[];let id=goal.id;while(id!==null){chain.unshift(this.byId.get(id));id=from.get(id);}let valid=true;for(let i=1;i<chain.length;i++)if(!this.transition(chain[i-1],chain[i]))valid=false;if(!valid)continue;
   const result=[this.center(start)];for(let i=1;i<chain.length;i++){const via=chain[i-1].via?.[chain[i].id];if(via)result.push(via);result.push(this.center(chain[i]));}const target={x:tx,z:tz,floor:targetFloor};if(this.trace(this.center(goal),target))result.push(target);return result;
  }return[];
 }

 spawn(attacking,i=0){const list=this.data.spawns[attacking?'attack':'defend'];const s=list[i%list.length];if(!s)throw Error('地图缺少出生点');const target=attacking?this.data.sites[0]:this.data.spawns.attack[0];return this.safePoint({...s,yaw:s.yaw??Math.atan2(s.x-target.x,s.z-target.z)});}
}
